input.command:
docker inspect weaknet-arm64-dev --format '
Image: {{.Config.Image}}
Cmd: {{json .Config.Cmd}}
Entrypoint: {{json .Config.Entrypoint}}
Env: {{json .Config.Env}}
WorkingDir: {{.Config.WorkingDir}}
Mounts: {{json .Mounts}}
RestartPolicy: {{.HostConfig.RestartPolicy.Name}}
NetworkMode: {{.HostConfig.NetworkMode}}
Privileged: {{.HostConfig.Privileged}}
'

python3 -c "
import json, glob
for f in sorted(glob.glob('/home/ubuntu/.claude/projects/-home-ubuntu-AI-powered-Network-Diagnostics/*.jsonl')):
    with open(f) as fp:
        lines = fp.readlines()
    cwds = set()
    for line in lines[:50]:
        try:
            d = json.loads(line)
            if d.get('cwd'): cwds.add(d['cwd'])
            att = d.get('attachment',{})
            snap = att.get('snapshot',{}) if isinstance(att,dict) else {}
            if snap.get('workingDirectory'): cwds.add(snap['workingDirectory'])
        except: pass
    print(f.split('/')[-1][:12], len(lines), 'recs,', 'cwds:', cwds)
"

