#!/usr/bin/env python3
"""WeakNet 实验室蓝牙配对 Agent（仅白名单两台手机自动接受）。

解决的问题：bluetoothd 日志 "Authentication attempt without agent"
导致手机连接时 profile/配对鉴权被 org.bluez.Error.Rejected 拒绝。
本 agent 注册为 default-agent，对白名单 MAC 自动确认所有鉴权请求，
其余设备一律 Rejected（不放行陌生人配对）。
"""
import dbus
import dbus.exceptions
import dbus.service
import dbus.mainloop.glib
from gi.repository import GLib

# 实验白名单：vivo X300s + iQOO Neo9（本测试的两台手机）
WHITELIST = {
    "/org/bluez/hci0/dev_D0_96_EA_52_30_AC",  # vivo X300s
    "/org/bluez/hci0/dev_A8_6F_36_6E_B7_90",  # iQOO Neo9
}
AGENT_PATH = "/org/weaknet/BtAgent"
REJECT = dbus.exceptions.DBusException("org.bluez.Error.Rejected")


def _check(path):
    if path not in WHITELIST:
        raise REJECT


class WeakNetAgent(dbus.service.Object):
    @dbus.service.method("org.bluez.Agent1")
    def Release(self):
        pass

    @dbus.service.method("org.bluez.Agent1", in_signature="o", out_signature="s")
    def RequestPinCode(self, device):
        _check(device)
        return "0000"

    @dbus.service.method("org.bluez.Agent1", in_signature="os")
    def DisplayPinCode(self, device, pincode):
        _check(device)

    @dbus.service.method("org.bluez.Agent1", in_signature="o", out_signature="u")
    def RequestPasskey(self, device):
        _check(device)
        return dbus.UInt32(0)

    @dbus.service.method("org.bluez.Agent1", in_signature="ouq")
    def DisplayPasskey(self, device, passkey, entered):
        _check(device)

    @dbus.service.method("org.bluez.Agent1", in_signature="ou", out_signature=None)
    def RequestConfirmation(self, device, passkey):
        _check(device)   # 手机弹"配对？"，板端自动确认

    @dbus.service.method("org.bluez.Agent1", in_signature="o", out_signature=None)
    def RequestAuthorization(self, device):
        _check(device)

    @dbus.service.method("org.bluez.Agent1", in_signature="os", out_signature=None)
    def AuthorizeService(self, device, uuid):
        _check(device)   # A2DP/HFP 等 profile 连接鉴权

    @dbus.service.method("org.bluez.Agent1", in_signature="o")
    def Cancel(self, device):
        pass


def main():
    dbus.mainloop.glib.DBusGMainLoop(set_as_default=True)
    bus = dbus.SystemBus()
    agent = WeakNetAgent(bus, AGENT_PATH)
    manager = dbus.Interface(
        bus.get_object("org.bluez", "/org/bluez"), "org.bluez.AgentManager1"
    )
    manager.RegisterAgent(AGENT_PATH, "KeyboardDisplay")
    manager.SetDefaultAgent(AGENT_PATH)
    print("weaknet-bt-agent registered (capability=KeyboardDisplay, whitelist=2 phones)")
    GLib.MainLoop().run()


if __name__ == "__main__":
    main()
PYEOF
sudo chmod +x /usr/local/bin/weaknet-bt-agent.py && echo "agent 脚本已写入" && sudo tee /etc/systemd/system/weaknet-bt-agent.service > /dev/null <<'"'"'EOF'"'"'
[Unit]
Description=WeakNet lab Bluetooth pairing agent (whitelist 2 phones)
After=bluetooth.service
Requires=bluetooth.service

[Service]
ExecStart=/usr/bin/python3 /usr/local/bin/weaknet-bt-agent.py
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF
